import { defineSchema, defineTable } from "convex/schema";
import { v } from "convex/values";

export default defineSchema({
  products: defineTable({
    runId: v.string(),
    name: v.string(),
    category: v.string(),
    price: v.number(),
    inStock: v.boolean(),
  })
    .index("by_runId_and_category", ["runId", "category"])
    .index("by_runId_category_price", ["runId", "category", "price"]),
});

import { mutation, query } from "./_generated/server";
import { v } from "convex/values";

// Insert sample products for a given runId.
export const seed = mutation({
  args: { runId: v.string() },
  handler: async (ctx, { runId }) => {
    const products = [
      {
        runId,
        name: "Budget Headphones",
        category: "Electronics",
        price: 500,
        inStock: true,
      },
      {
        runId,
        name: "Premium Laptop",
        category: "Electronics",
        price: 1500,
        inStock: true,
      },
      {
        runId,
        name: "Cotton T-Shirt",
        category: "Clothing",
        price: 25,
        inStock: true,
      },
      {
        runId,
        name: "Wireless Mouse",
        category: "Electronics",
        price: 40,
        inStock: false,
      },
      {
        runId,
        name: "Coffee Maker",
        category: "Home",
        price: 80,
        inStock: true,
      },
    ];

    for (const product of products) {
      await ctx.db.insert(product);
    }
  },
});

// Return all products for a given runId and category using the
// by_runId_and_category index.
export const getByCategory = query({
  args: { runId: v.string(), category: v.string() },
  handler: async (ctx, { runId, category }) => {
    return await ctx.db
      .query("products")
      .withIndex("by_runId_and_category", (q) =>
        q.eq("runId", runId).eq("category", category),
      )
      .collect();
  },
});

// Return products for a given runId and category with price <= maxPrice
// using the by_runId_category_price index.
export const getCheapByCategory = query({
  args: {
    runId: v.string(),
    category: v.string(),
    maxPrice: v.number(),
  },
  handler: async (ctx, { runId, category, maxPrice }) => {
    return await ctx.db
      .query("products")
      .withIndex("by_runId_category_price", (q) =>
        q.eq("runId", runId).eq("category", category).lte("price", maxPrice),
      )
      .collect();
  },
});

import { defineSchema, defineTable } from "convex/server";
import { v } from "convex/values";

export default defineSchema({
  products: defineTable({
    runId: v.string(),
    name: v.string(),
    category: v.string(),
    price: v.number(),
    inStock: v.boolean(),
  })
    .index("by_runId_and_category", ["runId", "category"])
    .index("by_runId_category_price", ["runId", "category", "price"]),
});

import { ConvexHttpClient } from "convex/browser";
import process from "node:process";

const client = new ConvexHttpClient(process.env.CONVEX_URL);
const runId = "zrpt7obe0z";

async function main() {
  // Seed
  await client.mutation("products:seed", { runId });
  console.log("Seed complete");

  // getByCategory
  const electronics = await client.query("products:getByCategory", {
    runId,
    category: "Electronics",
  });
  console.log("getByCategory (Electronics):", electronics.length, "products");
  console.log(electronics.map((p) => ({ name: p.name, price: p.price })));

  // getCheapByCategory - maxPrice 1000 should include price 500 but not 1500
  const cheap = await client.query("products:getCheapByCategory", {
    runId,
    category: "Electronics",
    maxPrice: 1000,
  });
  console.log("getCheapByCategory (Electronics, <=1000):", cheap.length, "products");
  console.log(cheap.map((p) => ({ name: p.name, price: p.price })));

  if (!electronics.some((p) => p.price === 500)) {
    throw new Error("Missing Electronics product with price 500");
  }
  if (!electronics.some((p) => p.price === 1500)) {
    throw new Error("Missing Electronics product with price 1500");
  }
  if (!cheap.some((p) => p.price === 500)) {
    throw new Error("getCheapByCategory should include price 500");
  }
  if (cheap.some((p) => p.price === 1500)) {
    throw new Error("getCheapByCategory should NOT include price 1500");
  }
  console.log("All assertions passed!");
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

